WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code, channel ORDER BY discount_pct DESC, id) AS dedup_rank FROM promotions QUALIFY dedup_rank = 1) SELECT id, promo_code, starts_on, ends_on, discount_pct, dedup_rank, CASE WHEN promo_code RLIKE '^(BUNDLE|WELCOME5)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS promo_code_zone FROM deduped ORDER BY promo_code DESC NULLS LAST, promo_code_zone DESC;
